.col-status { width: 6px; min-width: 6px; padding: 0 !important; }
.dash-table th.col-status, .dash-table td.col-status { width: 6px; min-width: 6px; padding: 0 !important; background: transparent; }
.dash-table td.col-status::before { content: "\00a0"; display: inline-block; width: 6px; }
.dash-table tr.has-err td.col-status { background: var(--dash-err-soft); }
.dash-table tr.has-abort td.col-status { background: var(--dash-abort-soft); }
.dash-table tr.all-ok td.col-status { background: var(--dash-ok-soft); }

.dash-table td.col-time { color: var(--muted); font-family: ui-monospace, Menlo, monospace; white-space: nowrap; }
