.dash-table td.col-id a:hover { text-decoration: underline; }
.dash-table td.col-prompt { color: var(--text); max-width: 460px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dash-table td.col-prompt.empty { color: var(--muted); font-style: italic; }
.dash-table td.col-cwd { color: var(--muted); font-family: ui-monospace, Menlo, monospace; white-space: nowrap; }
